"""Copy Eureka Orthos combat walls/traps, excluding routes and interactions."""
from pathlib import Path
import argparse
import json
import re
from generate_palace_floor_data import arguments

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "MechanicRuntime/Upstream/Modules/Global/DeepDungeon"
TARGET = ROOT / "Presets/EurekaOrthos/Floor/EurekaFloorData.cs"
TERRITORIES = range(1099, 1109)


def generate(check):
    source = (SOURCE / "LoadedFloors.cs").read_text(encoding="utf-8-sig")
    lines = [
        "// Generated by tools/generate_eureka_floor_data.py from MIT BMR coordinates.",
        "using System.Numerics;", "using MasterPlayer.Mechanics.PalaceOfTheDead;", "",
        "namespace MasterPlayer.Mechanics.EurekaOrthos;", "",
        "internal static class EurekaFloorData", "{",
        "    internal static readonly Dictionary<(int FloorSet, byte Tileset), PalaceFloorRoom[]> Rooms = new()", "    {",
    ]
    count = 0
    for floorset in range(1, 11):
        block = source.split(f'["3.{floorset}"] = new(', 1)[1].split('["', 1)[0]
        tilesets = re.findall(r"new Tileset<Wall>\(\s*\[(.*?)\]\)", block, re.S)
        assert len(tilesets) == 2
        for tileset, text in enumerate(tilesets):
            lines += [f"        [({floorset}, {tileset})] =", "        ["]
            rows = [line.strip() for line in text.splitlines() if line.strip()]
            assert len(rows) == 25
            for row in rows:
                args = arguments(row.removeprefix("new(").removesuffix("),"))
                assert len(args) == 5
                center = args[0]
                if center != "default":
                    center = "new(" + re.fullmatch(r"new\(new\((.*?)\), .*?\)", center)[1] + ")"
                lines.append(f"            new({center}, {', '.join(args[1:])}),")
                count += 1
            lines.append("        ],")
    assert count == 500
    lines += ["    };", "", "    internal static readonly Dictionary<ushort, Vector2[]> Traps = new()", "    {"]
    source = (SOURCE / "TrapData.cs").read_text(encoding="utf-8-sig")
    trap_count = 0
    for territory in TERRITORIES:
        body = re.search(r"\{\s*" + str(territory) + r", \[(.*?)\]\}", source, re.S)[1]
        traps = re.findall(r"new\(([^)]+)\)", body)
        assert traps
        trap_count += len(traps)
        lines += [f"        [{territory}] =", "        ["]
        for i in range(0, len(traps), 4):
            lines.append("            " + ", ".join(f"new({t})" for t in traps[i:i + 4]) + ",")
        lines.append("        ],")
    lines += ["    };", "}", ""]
    assert trap_count == 3188
    text = "\n".join(lines)
    if check:
        if TARGET.read_text(encoding="utf-8") != text:
            raise SystemExit("Eureka Orthos combat coordinates differ; regenerate.")
    else:
        TARGET.parent.mkdir(parents=True, exist_ok=True)
        TARGET.write_text(text, encoding="utf-8", newline="\n")
    print(f"{'Checked' if check else 'Generated'} EO {count} rooms/{trap_count} traps in {len(TERRITORIES)} territories.")
    maps = ROOT / "MechanicRuntime/Upstream/Pathfinding/ObstacleMaps"
    destination = TARGET.parent / "ObstacleMaps"
    source_maps = json.loads((maps / "maplist.json").read_text(encoding="utf-8-sig"))
    selected = {key: value for key, value in source_maps.items()
                if int(key.split(".")[0]) in TERRITORIES}
    filenames = [entry["Filename"] for entries in selected.values() for entry in entries]
    assert len(filenames) == 24 and len(set(filenames)) == 24
    if check:
        assert json.loads((destination / "maplist.json").read_text(encoding="utf-8-sig")) == selected
        for name in filenames:
            assert (destination / name).read_bytes() == (maps / name).read_bytes(), name
    else:
        destination.mkdir(parents=True, exist_ok=True)
        (destination / "maplist.json").write_text(json.dumps(selected, ensure_ascii=False, indent=2) + "\n",
                                                encoding="utf-8", newline="\n")
        for name in filenames:
            (destination / name).write_bytes((maps / name).read_bytes())
    print(f"{'Checked' if check else 'Generated'} EO 24 unchanged LOS bitmaps and source metadata.")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    generate(parser.parse_args().check)
